/** The country with this code, or undefined. */
export function countryByCode(code: string | null | undefined): Country | undefined {
  return code ? COUNTRIES.find((c) => c.code === code) : undefined;
}

const normalise = (s: string) =>
  s.toLowerCase().replace(/&/g, " and ").replace(/[^a-z]/g, "");

/** The code for a typed country name (or alias), or null. Mirrors `public.country_code_for()`. */
export function countryCodeFor(name: string | null | undefined): string | null {
  if (!name) return null;
  const n = normalise(name);
  if (!n) return null;
  const hit = COUNTRIES.find((c) => normalise(c.name) === n || (c.aliases ?? []).some((a) => normalise(a) === n));
  return hit ? hit.code : null;
}
